import csv, json, os, glob

with open('Oct_Orchestrate/dataset/sample_output.csv', encoding='utf-8') as f:
    s_outs = {r['case_id']: json.loads(r['steps_json']) for r in csv.DictReader(f)}

with open('Oct_Orchestrate/dataset/system_activity.csv', encoding='utf-8') as f:
    acts = list(csv.DictReader(f))

all_sample_resources = set()
for steps in s_outs.values():
    for step in steps:
        all_sample_resources.add(step['resource_id'])

act_resources = {a['resource_id'] for a in acts}
missing = all_sample_resources - act_resources
print('Missing from system_activity:', list(missing)[:10])

# Search in evidence files
found_in_evidence = {}
for root, dirs, files in os.walk('Oct_Orchestrate/dataset/evidence'):
    for file in files:
        if file.endswith(('.txt', '.json', '.log', '.sql')):
            p = os.path.join(root, file)
            with open(p, 'r', encoding='utf-8', errors='ignore') as f:
                content = f.read()
                for m in missing:
                    if m in content:
                        found_in_evidence.setdefault(m, []).append(file)

print(f'Missing resources found in evidence files: {len(found_in_evidence)} / {len(missing)}')
for m in list(missing)[:5]:
    print(m, 'found in:', found_in_evidence.get(m))
